import React, { useState, useEffect } from 'react';

const FilterPanel = ({ products, onFilterChange }) => {
  const [filters, setFilters] = useState({
    priceRange: [0, 1000],
    rating: 0,
    ratingMin: 0,
    ratingMax: 5
  });

  const [expanded, setExpanded] = useState(true);

  // Extract unique platforms from products
  const platforms = Array.from(new Set(products.map(p => p.platform).filter(Boolean)));
  const [selectedPlatforms, setSelectedPlatforms] = useState(platforms);

  useEffect(() => {
    if (products && products.length > 0) {
      // Find max price for the range
      const maxPrice = Math.max(...products.map(product => product.price || 0)) + 100;
      setFilters(prev => ({
        ...prev,
        priceRange: [0, maxPrice]
      }));
    }
  }, [products]);

  // Handle price range change
  const handlePriceChange = (e, index) => {
    const value = parseFloat(e.target.value);
    const newRange = [...filters.priceRange];
    newRange[index] = value;

    // Ensure min <= max
    if (index === 0 && value > newRange[1]) {
      newRange[1] = value;
    } else if (index === 1 && value < newRange[0]) {
      newRange[0] = value;
    }

    setFilters({
      ...filters,
      priceRange: newRange
    });
  };

  // Handle rating filter change
  const handleRatingChange = (e) => {
    const value = parseInt(e.target.value);
    setFilters({
      ...filters,
      rating: value
    });
  };

  // Handle platform filter change
  const handlePlatformChange = (platform) => {
    setSelectedPlatforms(prev =>
      prev.includes(platform)
        ? prev.filter(p => p !== platform)
        : [...prev, platform]
    );
  };

  // Apply filters
  useEffect(() => {
    onFilterChange({
      ...filters,
      platforms: selectedPlatforms
    });
  }, [filters, selectedPlatforms, onFilterChange]);

  // Toggle panel expansion
  const toggleExpand = () => {
    setExpanded(!expanded);
  };

  const handleFilterChange = () => {
    onFilterChange({
      ...filters,
      platforms: selectedPlatforms
    });
  };

  return (
    <div className={`filter-panel ${expanded ? 'expanded' : 'collapsed'}`}>
      <div className="filter-header" onClick={toggleExpand}>
        <h4>
          <i className="fas fa-filter"></i> Filter
        </h4>
        <button className="expand-toggle">
          <i className={`fas fa-chevron-${expanded ? 'up' : 'down'}`}></i>
        </button>
      </div>

      {expanded && (
        <div className="filter-content">
          {/* Price Range Filter */}
          <div className="filter-section">
            <h5>Price Range</h5>
            <div className="price-inputs" style={{ gap: '1rem', marginBottom: '0.5rem' }}>
              <div className="input-group" style={{ width: '120px', minWidth: '0' }}>
                <span className="input-group-text">$</span>
                <input
                  type="number"
                  className="form-control min-price"
                  value={filters.priceRange[0]}
                  onChange={(e) => handlePriceChange(e, 0)}
                  min="0"
                  style={{ fontSize: '1.1rem', height: '2.2rem' }}
                />
              </div>
              <span className="price-separator">to</span>
              <div className="input-group" style={{ width: '120px', minWidth: '0' }}>
                <span className="input-group-text">$</span>
                <input
                  type="number"
                  className="form-control max-price"
                  value={filters.priceRange[1]}
                  onChange={(e) => handlePriceChange(e, 1)}
                  min={filters.priceRange[0]}
                  style={{ fontSize: '1.1rem', height: '2.2rem' }}
                />
              </div>
            </div>
          </div>

          {/* Platforms Filter */}
          <div className="filter-section">
            <h5>Platforms</h5>
            {platforms.map(platform => (
              <div className="form-check" key={platform}>
                <input
                  className="form-check-input"
                  type="checkbox"
                  id={`platform-${platform}`}
                  checked={selectedPlatforms.includes(platform)}
                  onChange={() => handlePlatformChange(platform)}
                />
                <label className="form-check-label" htmlFor={`platform-${platform}`}>
                  {platform}
                </label>
              </div>
            ))}
          </div>

          {/* Rating Filter */}
          <div className="filter-section">
            <h5>Rating Range</h5>
            <div className="rating-range-inputs" style={{ display: 'flex', alignItems: 'center', gap: '1rem', marginBottom: '0.5rem' }}>
              <input
                type="number"
                className="form-control min-rating"
                min="0"
                max="5"
                step="0.1"
                value={filters.ratingMin !== undefined ? filters.ratingMin : 0}
                onChange={e => setFilters({ ...filters, ratingMin: parseFloat(e.target.value) })}
                style={{ width: '60px', fontSize: '1.1rem', height: '2.2rem' }}
              />
              <span className="price-separator">to</span>
              <input
                type="number"
                className="form-control max-rating"
                min={filters.ratingMin !== undefined ? filters.ratingMin : 0}
                max="5"
                step="0.1"
                value={filters.ratingMax !== undefined ? filters.ratingMax : 5}
                onChange={e => setFilters({ ...filters, ratingMax: parseFloat(e.target.value) })}
                style={{ width: '60px', fontSize: '1.1rem', height: '2.2rem' }}
              />
            </div>
          </div>

          {/* Reset Filters Button */}
          <button
            className="btn btn-outline-secondary reset-filters-btn"
            onClick={() => {
              setFilters({
                priceRange: [0, Math.max(...products.map(product => product.price || 0)) + 100],
                rating: 0,
                ratingMin: 0,
                ratingMax: 5
              });
              setSelectedPlatforms(platforms);
            }}
          >
            Reset Filters
          </button>

          {/* Apply Filters Button */}
          <button onClick={handleFilterChange}>Apply Filters</button>
        </div>
      )}
    </div>
  );
};

export default FilterPanel;
